const statusBadge=s=>{const [label,color]=stageLabels[s]||[s,'gray'];return `<span class="badge ${color}">${esc(wfQuoteLabel(s,label))}</span>`};
const statusPill=(s,c)=>`<span class="badge ${c}">${esc(s)}</span>`;
let db;try{db=JSON.parse(localStorage.getItem(STORE));if(!db||db.version!==4)db=seed()}catch{db=seed()}
