let selected=new Set(),search='',filterStatus='',filterSupplier='',formatFilter='',priceFilter='',costTab='material',editing=null,editorAttachments=[];
const itemOf=q=>db.items.find(i=>i.id===q.item);
const isIncompleteQuote=q=>q.status==='Draft'&&!!validateCosts(q.costs);
