function dialog(title,body,footer,cls=''){document.getElementById('modal-root').innerHTML=`<div class="modal-shade"><section class="dialog ${cls}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></header><div class="dialog-body">${body}</div><footer class="dialog-footer">${actionButton('Cancel','close')}${footer}</footer></section></div>`;document.querySelector('.dialog button')?.focus();}
function closeDialog(){document.getElementById('modal-root').innerHTML=''}
let transitionPending=null;
function transitionDialog(id,kind){const q=visibleQuotes().find(q=>q.id===id);if(!q||!pendingForRole(q))return toast('This action is not assigned to your account.');transitionPending={id,kind};const advance=kind==='advance';dialog(advance?(portal==='supplier'?'Approve supplier quotation':'Confirm ROKI '+user.role.toLowerCase()):kind==='revert'?'Return quotation for correction':'Reject quotation',`<p><strong>${esc(q.id)}</strong> · ${esc(itemOf(q).name)}<br>Proposed unit price <strong>฿${cash(q.total)}</strong></p><p style="margin-top:15px">${advance?(portal==='supplier'?'Approving submits this quotation to the WEBPARK Check queue.':'This records a simulated e-sign confirmation for '+esc(user.name)+'.'):(kind==='revert'?'Return to the supplier issuer for correction. A reason is required.':'Reject this quotation. The supplier must prepare a new quotation. A reason is required.')}</p><div class="field"><label for="action-reason">${advance?'Review note (optional)':'Reason *'}</label><textarea id="action-reason" maxlength="1000" placeholder="${advance?'Add a review note…':'Explain what needs to change…'}"></textarea></div>${advance?`<label style="display:flex;gap:9px;font-size:11px;color:#75879e;align-items:flex-start;margin-top:18px"><input id="confirm-action" type="checkbox">I confirm this review as ${esc(user.name)}, ${esc(user.role)}.</label>`:''}`,actionButton(advance?'Confirm '+(portal==='supplier'?'approval':'review'):kind==='revert'?'Return for correction':'Reject quotation','confirm-transition',true));}
function confirmTransition(){if(!transitionPending)return;const {id,kind}=transitionPending,q=visibleQuotes().find(q=>q.id===id);if(!q||!pendingForRole(q))return toast('Quotation is no longer assigned to this role.');const reason=document.getElementById('action-reason').value.trim();if(kind!=='advance'&&!reason)return toast('A reason is required.');if(kind==='advance'&&!document.getElementById('confirm-action').checked)return toast('Confirm your review before continuing.');const item=itemOf(q),tag=`[ROKI Supplier Price] ${q.id} · ${item.code}`,supplierTeam=usersOf('supplier',null,q.supplier);let action,stage;
if(kind==='revert'){q.status='Reverted';action='Returned to supplier issuer for correction';email(portal==='roki'?supplierTeam:usersOf('supplier','Issue',q.supplier),`${tag} returned for correction`,`${user.name} (${portal==='roki'?'ROKI':'Supplier'} ${user.role}) returned the quotation. Reason: ${reason}`,q.id);}
else if(kind==='reject'){q.status='Rejected';action='ROKI rejected quotation';email(supplierTeam,`${tag} rejected`,`ROKI ${user.role} ${user.name} rejected this quotation. Please prepare a new quotation. Reason: ${reason}`,q.id);}
else{const next={'Supplier approval':'ROKI Check','ROKI Issue':'ROKI Check','ROKI Check':'ROKI Approve','ROKI Approve':'Approved'};q.status=next[q.status];stage=portal==='supplier'?'S-Approve':'R-'+user.role;action=STAGES.find(s=>s[0]===stage)[1];
if(q.status==='Approved'){q.approvedAtISO=new Date().toISOString();syncActivePrices();item.last=TODAY;if(item.next)item.next=addMonths(q.effective>TODAY?q.effective:TODAY,item.cadence||3);db.history.push({item:item.id,effective:q.effective,price:q.total,quote:q.id,reason:q.remark});email(supplierTeam,`${tag} approved by ROKI`,`Quotation ${q.id} is approved at ฿${cash(q.total)} per piece, effective ${date(q.effective)}.`,q.id);}
else{const role=q.status.replace('ROKI ','');email(usersOf('roki',role),`${tag} waiting for ROKI ${role}`,`${user.name} completed ${portal==='supplier'?'supplier approval':'ROKI '+user.role}. Proposed price ฿${cash(q.total)} (${q.previous==null?'first quotation':'previous ฿'+cash(q.previous)+', '+signedPct(q.total,q.previous)}).`,q.id);}}
q.trail.push({stage,action,user:user.name,at:timestamp(),reason});audit(action+' · '+q.id,reason);closeDialog();transitionPending=null;render();toast('Quotation updated: '+stageLabels[q.status][0]+' · email notification queued (demo)');}
function notifyDialog(){return rfqDraftDialog()}
function sendNotifications(){return rfqSave(false)}
function download(name,content,type='text/csv;charset=utf-8'){name=name.replace(/^roki-/i,'webpark-');content=CompanyBrand.text(content);const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const ordinal=n=>n===1?'1st':n===2?'2nd':n===3?'3rd':n+'th';
function formColumn(title,costs,meta,item,q){const t=totals(costs),secs=sectionsOf(costs);
const sec=s=>{const rows=costs[s.key]||[],x=t.sections[s.key];return `<table class="qt-table"><caption>${s.label} breakdown (${s.letter})</caption><thead><tr>${s.fields.map(f=>`<th>${f[1].replace(/ · .*/,'')}</th>`).join('')}<th>Amount</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${s.fields.map(f=>`<td class="${f[2]==='number'?'num':''}">${f[2]==='number'?Number(r[f[0]]).toLocaleString('en-US',{maximumFractionDigits:6}):esc(r[f[0]]||'')}</td>`).join('')}<td class="num">${cash(amountOf(costs,s,r))}</td></tr>`).join(''):`<tr><td colspan="${s.fields.length+1}" class="blank">—</td></tr>`}${(s.adj||[]).filter(a=>costs[a.key]).map(a=>`<tr><td colspan="${s.fields.length}">${a.label} ${costs[a.key]}%${a.choices?` × ${adjChoice(costs,a).of==='self'?s.letter:(secs.find(x=>x.key===adjChoice(costs,a).of)||s).letter}`:''}</td><td class="num">${cash(x.extra)}</td></tr>`).join('')}<tr class="qt-total"><td colspan="${s.fields.length}">Total</td><td class="num">${cash(t[s.letter])}</td></tr></tbody></table>`};
return `<div class="qt-col"><div class="qt-col-title">${esc(title)}</div><div class="qt-head"><span>Date: <b>${date(meta.date)}</b></span><span>Part No.: <b>${esc(item.code)}</b></span><span>Rev. No.: <b>${esc(meta.drawing||'—')}</b></span><span>${esc(qtyLabelOf(meta.qtyPeriod,item.format))}: <b>${meta.qty==null?'—':Number(meta.qty).toLocaleString()}</b></span><span>RTP code: <b>${esc(item.rtp||'')}</b></span><span>Part name: <b>${esc(item.name)}</b></span></div>${secs.map(sec).join('')}<table class="qt-table qt-sum"><tbody><tr><td>(${secs.map(s=>s.letter).join('+')})</td><td class="num">${cash(t.subtotal)}</td></tr><tr><td>Profit & admin cost (${profitBase(costs).short}) × ${costs.profit}%</td><td class="num">${cash(t.profit)}</td></tr>${costs.spare?`<tr><td>Spare part cost (${spareBase(costs).short}) × ${costs.spare}%</td><td class="num">${cash(t.spare)}</td></tr>`:''}<tr class="qt-grand"><td>Total</td><td class="num">${cash(t.total)}</td></tr></tbody></table><div class="qt-remark"><b>Remark:</b> ${esc(meta.remark||'')}<div class="qt-begin">Beginning: <b>${date(meta.effective)}</b>${meta.ending?` · Ending: <b>${date(meta.ending)}</b>`:''}</div></div></div>`}
function printView(id){const q=visibleQuotes().find(q=>q.id===id);if(!q)return '<div class="empty">Quotation unavailable for this account. <a href="#quotes" class="link-button">Return to quotations</a></div>';const item=quotationIdentity(q),sup=suppliers.find(s=>s.id===q.supplier),b=q.baseline,sig=signatures(q);
const box=(stage,label,roki)=>{const s=sig[stage];return `<div class="qt-sign"><small>${label}</small>${s?`<div class="qt-signed ${roki?'esign':''}">${esc(s.user)}<em>${roki?'e-signed':'confirmed in system'} · ${esc(s.at)}</em></div>`:'<div class="qt-signed pending">Pending</div>'}</div>`};
return `<div class="no-print">${heading('Quotation form · '+q.id,item.name,'Printable layout of the ROKI quotation sheet. Use your browser’s Save as PDF to file or share it.',`<a href="#quote/${q.id}" class="button">Back to quotation</a><button type="button" class="button primary" data-action="print">${icon('download')}Print / save PDF</button>`)}${q.status!=='Approved'?`<div class="highlight-note">Status: ${esc(stageLabels[q.status][0])}. Signature boxes fill in as each step is completed.</div>`:''}</div><article class="qt-form"><header class="qt-letterhead">${logo()}<div><strong>${CompanyBrand.name}</strong><span>${wfText("Supplier Price Workspace","ระบบจัดการราคา Supplier")}</span></div><div class="qt-title">QUOTATION (${q.format==='Assembly'?'Assembly':'Unit Part'})<small>${esc(q.id)}</small></div></header><div class="qt-supplier">Supplier code: <b>${esc(sup.code)}</b>　Supplier name: <b>${esc(sup.name)}</b></div>${b&&(b.quantity==null||!b.drawing)?`<p class="muted-note">${wfText("Some original header data was not recorded; unknown values are shown as —.","ข้อมูลหัวใบต้นฉบับบางส่วนไม่ได้บันทึกไว้ จะแสดง — แทนค่าที่ไม่ทราบ")}</p>`:''}<div class="qt-cols ${b?'two':''}">${b?formColumn(b.revision?'Cost Revise '+ordinal(b.revision):'Cost Original',b.costs,{date:b.date,drawing:b.drawing,qty:b.quantity,remark:b.remark,effective:b.effective,ending:b.ending,qtyPeriod:b.qtyPeriod},b.itemSnapshot||item,q):''}${formColumn(q.revision?'Cost Revise '+ordinal(q.revision):'Cost Original',q.costs,{date:q.quoteDate,drawing:q.drawing,qty:q.quantity,remark:q.remark,effective:q.effective,ending:q.ending,qtyPeriod:q.qtyPeriod},item,q)}</div><footer class="qt-signs"><div><h3>${wfText("Supplier confirmation (no e-sign)","Supplier ยืนยันอนุมัติ (ไม่ต้อง E-sign)")}</h3><div class="qt-sign-row">${box('S-Approve','Approved by')}${box('S-Issue','Issued by')}</div></div><div><h3>${wfText("WEBPARK e-sign approvals","WEBPARK ยืนยันอนุมัติด้วย E-sign")}</h3><div class="qt-sign-row">${box('R-Approve','Approved by',true)}${box('R-Check','Checked by',true)}${q.flowVersion===2?'':box('R-Issue','Issued by',true)}</div></div></footer><p class="qt-foot">${(q.terms?termsLines(q.terms):['This unit price excludes VAT']).map(esc).join(' · ')} · Generated by ROKI Supplier Price demo · E-signatures are simulated</p></article>`}
const SERIES_COLORS=['#2a78d6','#eb6834','#1baf7a','#eda100'];
function historyItems(){return db.items.filter(i=>portal==='roki'||i.supplier===user.supplier)}
function priceChart(code){const items=historyItems().filter(i=>familyMatches(i,code));const series=items.map((it,k)=>({it,color:SERIES_COLORS[k%4],pts:db.history.filter(h=>h.item===it.id).sort((a,b)=>a.effective.localeCompare(b.effective))})).filter(s=>s.pts.length);if(!series.length)return '<div class="empty">No approved prices recorded for this part.</div>';
const pending=db.quotes.filter(q=>items.some(i=>i.id===q.item)&&!['Approved','Rejected','Draft'].includes(q.status)&&(portal==='supplier'||!['Supplier approval'].includes(q.status)));
const ts=d=>new Date(d+'T00:00:00').getTime(),all=series.flatMap(s=>s.pts),x0=Math.min(...all.map(p=>ts(p.effective))),x1=Math.max(ts(TODAY),...all.map(p=>ts(p.effective)),...pending.map(q=>ts(q.effective)));
const prices=[...all.map(p=>p.price),...pending.map(q=>q.total)],lo=Math.min(...prices),hi=Math.max(...prices),pad=(hi-lo||hi*.1)*.15,y0=Math.max(0,lo-pad),y1=hi+pad;
const W=760,H=270,L=56,R=150,T=16,B=34,X=t=>L+(t-x0)/(x1-x0||1)*(W-L-R),Y=v=>T+(1-(v-y0)/(y1-y0||1))*(H-T-B);
const ticks=[0,1,2,3,4].map(i=>y0+(y1-y0)*i/4);const years=[];for(let y=new Date(x0).getFullYear()+1;y<=new Date(x1).getFullYear();y++)years.push(y);
const lines=series.map(s=>{let d='';s.pts.forEach((p,i)=>{const x=X(ts(p.effective)),y=Y(p.price);d+=i?`H${x.toFixed(1)}V${y.toFixed(1)}`:`M${x.toFixed(1)} ${y.toFixed(1)}`});d+=`H${X(Math.max(ts(TODAY),ts(s.pts.at(-1).effective))).toFixed(1)}`;const last=s.pts.at(-1);
const marks=s.pts.map(p=>`<g class="pt" tabindex="0"><circle cx="${X(ts(p.effective))}" cy="${Y(p.price)}" r="12" fill="transparent"/><circle cx="${X(ts(p.effective))}" cy="${Y(p.price)}" r="4.5" fill="${s.color}" stroke="#fff" stroke-width="2"/><title>${esc(supplierName(s.it.supplier))} · ${date(p.effective)} · ฿${cash(p.price)}${p.quote?' · '+p.quote:''}</title></g>`).join('');
const pend=pending.filter(q=>q.item===s.it.id).map(q=>`<g class="pt" tabindex="0"><line x1="${X(ts(TODAY))}" y1="${Y(last.price)}" x2="${X(ts(q.effective))}" y2="${Y(q.total)}" stroke="${s.color}" stroke-width="2" stroke-dasharray="4 4"/><circle cx="${X(ts(q.effective))}" cy="${Y(q.total)}" r="4.5" fill="#fff" stroke="${s.color}" stroke-width="2"/><title>Pending ${esc(q.id)} · ${esc(stageLabels[q.status][0])} · ฿${cash(q.total)} from ${date(q.effective)}</title></g>`).join('');
return `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="2"/>${pend}${marks}<text x="${W-R+8}" y="${Y(last.price)+4}" class="chart-label">${esc(supplierName(s.it.supplier).split(' ').slice(0,2).join(' '))} ฿${cash(last.price)}</text>`}).join('');
return `<div class="chart-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(supplierName(s.it.supplier))}</span>`).join('')}${pending.length?'<span><i class="pending-swatch"></i>Pending revision</span>':''}</div><svg class="price-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Approved unit price over time for ${esc(code)}, one line per supplier">${ticks.map(v=>`<line x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" class="grid"/><text x="${L-8}" y="${Y(v)+3}" text-anchor="end" class="axis">${v.toFixed(2)}</text>`).join('')}${years.map(y=>{const x=X(new Date(y+'-01-01T00:00:00').getTime());return `<line x1="${x}" x2="${x}" y1="${T}" y2="${H-B}" class="grid"/><text x="${x}" y="${H-B+18}" text-anchor="middle" class="axis">${y}</text>`}).join('')}<line x1="${X(ts(TODAY))}" x2="${X(ts(TODAY))}" y1="${T}" y2="${H-B}" class="today"/><text x="${X(ts(TODAY))}" y="${T-4}" text-anchor="middle" class="axis">Today</text>${lines}</svg>`}
function reportsView(){const items=historyItems(),codes=[...new Set(items.map(familyKey))];const fromHash=decodeURIComponent(route().split('/')[1]||'');const code=codes.includes(fromHash)?fromHash:codes.includes(reportCode)?reportCode:(codes.find(c=>items.filter(i=>familyMatches(i,c)).length>1)||codes[0]);reportCode=code;
const rows=db.history.filter(h=>items.some(i=>i.id===h.item&&familyMatches(i,code))).sort((a,b)=>b.effective.localeCompare(a.effective));
const prevOf=h=>db.history.filter(x=>x.item===h.item&&x.effective<h.effective).sort((a,b)=>a.effective.localeCompare(b.effective)).at(-1);
const year=String(Number(TODAY.slice(0,4))-1)+TODAY.slice(4);
const summary=items.map(i=>{const h=db.history.filter(x=>x.item===i.id&&x.effective<=TODAY).sort((a,b)=>a.effective.localeCompare(b.effective)),last=h.at(-1),prev=h.at(-2);return {i,last,prev,count:h.filter(x=>x.effective>=year).length}}).filter(s=>s.last);
return heading('Traceability',portal==='roki'?'Price history report':'Price history','Every approved price per item and supplier, with the reason for each change.',portal==='roki'?actionButton('Download history CSV','export-history'):'')+`<section class="panel"><div class="panel-title"><div><h2>Unit price over time</h2><small>THB per piece · step changes at each effective date · dashed = revision still in approval</small></div><select id="report-code" aria-label="Part number">${codes.map(c=>`<option value="${esc(c)}" ${c===code?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="body-pad">${priceChart(code)}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Effective</th><th>${wfText("Item code","รหัสชิ้นส่วน")}</th><th>Supplier</th><th class="num">Unit price · THB</th><th class="num">Change</th><th>Quotation</th><th>Reason</th></tr></thead><tbody>${rows.map(h=>{const p=prevOf(h);return `<tr ${detailRowAttrs('price-record/'+db.history.indexOf(h))}><td>${date(h.effective)}</td><td>${esc(db.items.find(i=>i.id===h.item).code)}</td><td>${esc(supplierName(db.items.find(i=>i.id===h.item).supplier))}</td><td class="num price">${cash(h.price)}</td><td class="num delta ${p?(h.price<p.price?'down':h.price>p.price?'up':'same'):'same'}">${p?signedPct(h.price,p.price):'—'}</td><td>${h.quote?`<a class="link-button" href="#quote/${h.quote}">${esc(h.quote)}</a>`:'<small>Excel record</small>'}</td><td class="reason-cell">${esc(h.reason)}</td></tr>`}).join('')}</tbody></table></div></section><section class="panel" style="margin-top:22px"><div class="panel-title"><div><h2>All item–supplier pairs</h2><small>Latest approved change and number of approved changes in the last 12 months</small></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Part</th><th>Supplier</th><th class="num">Current · THB</th><th class="num">Previous · THB</th><th class="num">Last change</th><th class="num">Changes · 12 mo</th><th>Since</th></tr></thead><tbody>${summary.map(s=>`<tr class="clickable" data-report="${esc(s.i.code)}" ${detailRowAttrs('part/'+s.i.id)}><td><strong>${esc(s.i.code)}</strong><small>${esc(s.i.name)}</small></td><td>${esc(supplierName(s.i.supplier))}</td><td class="num price">${cash(s.last.price)}</td><td class="num">${s.prev?cash(s.prev.price):'—'}</td><td class="num delta ${s.prev?(s.last.price<s.prev.price?'down':s.last.price>s.prev.price?'up':'same'):'same'}">${s.prev?signedPct(s.last.price,s.prev.price):'—'}</td><td class="num">${s.count}</td><td>${date(s.last.effective)}</td></tr>`).join('')}</tbody></table></div></section>`}
function outboxView(){const mine=db.emails.filter(m=>portal==='roki'||m.to.some(id=>users.find(u=>u.id===id)?.supplier===user.supplier));return heading('Notifications','Email notifications','Emails the system sends at each workflow step. In this demo they are recorded here and not delivered.')+`<div class="highlight-note blue">Recipients follow the workflow: supplier approver after Issue → ROKI Issue → Check → Approve, and the supplier team when a quotation is returned, rejected or approved.</div><section class="panel"><div class="panel-title"><h2>${portal==='roki'?'All notifications':'Notifications to your company'}</h2>${statusPill(mine.length+' emails','gray')}</div>${mine.length?mine.map(m=>`<div class="notification-card"><div><h3>${esc(m.subject)}</h3><p>To: ${m.to.map(id=>{const u=users.find(u=>u.id===id);return u?`${esc(u.name)} &lt;${esc(u.email)}&gt;`:''}).join(', ')}</p><p>${esc(m.body)}</p><small>${esc(m.at)} · triggered by ${esc(m.by)}${m.quote&&visibleQuotes().some(q=>q.id===m.quote)?` · <a class="link-button" href="#quote/${esc(m.quote)}">${esc(m.quote)}</a>`:''}</small></div>${statusPill('Simulated · not sent','gray')}</div>`).join(''):'<div class="empty">No email notifications yet. They appear here when a quotation moves through the workflow.</div>'}</section>`}
function exportHistoryCSV(){if(portal!=='roki')return;const rows=[['Part code','Part name','Supplier code','Supplier','Effective date','Unit price THB','Quotation','Reason'],...db.history.slice().sort((a,b)=>a.effective.localeCompare(b.effective)).map(h=>{const i=db.items.find(x=>x.id===h.item),s=suppliers.find(s=>s.id===i.supplier);return [i.code,i.name,s.code,s.name,h.effective,h.price.toFixed(2),h.quote||'Excel record',h.reason]})];download('roki-price-history-demo.csv','﻿'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'));toast('Price history CSV downloaded.')}
const csvCell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';
function exportCSV(){if(portal!=='roki')return;const rows=[['Quotation','Part code','Part name','RTP code','Supplier code','Supplier','Format','Revision','Previous price THB','Approved price THB','Change %','Effective date','Reason'],...db.quotes.filter(q=>priceValidity(q)==='active').map(q=>{const i=itemOf(q),s=suppliers.find(s=>s.id===q.supplier);return [q.id,i.code,i.name,i.rtp||'',s.code,s.name,q.format,q.revision,q.previous==null?'':q.previous.toFixed(2),q.total.toFixed(2),q.previous?pctOf(q.total,q.previous).toFixed(2):'',q.effective,q.remark]})];download('roki-approved-prices-demo.csv','﻿'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'));toast('Approved prices CSV downloaded. This is not an SAP upload format.');}
function route(){return location.hash.slice(1)||'overview'}
// Keep the workspace chrome mounted while routes and filters replace only page content.
const chromeMarkup=new WeakMap();
function updateWorkspace(content,page){
 const app=document.getElementById('app'),template=document.createElement('template');
 template.innerHTML=shell(content,page);
 const next=template.content.querySelector('.layout'),current=app.querySelector(':scope > .layout');
 if(!current){
  app.replaceChildren(next);
  next.querySelectorAll('.sidebar > *, .main > .demo-banner, .main > .topline, .main > .mobile-nav').forEach(el=>{
   const copy=el.cloneNode(true);
   if(el.matches('.side-nav'))copy.querySelectorAll('a.active').forEach(a=>a.classList.remove('active'));
   chromeMarkup.set(el,copy.innerHTML);
  });
  next.querySelector('.sidebar .side-nav a.active')?.setAttribute('aria-current','page');
  return;
 }
 const sidebar=current.querySelector(':scope > .sidebar'),nextSidebar=next.querySelector(':scope > .sidebar');
 const activeHref=nextSidebar.querySelector('.side-nav a.active')?.getAttribute('href');
 nextSidebar.querySelectorAll('.side-nav a').forEach(a=>a.classList.remove('active'));
 // Counts, role or language can change without replacing the scroll containers.
 const syncChildren=(target,source)=>{
  const markup=source.innerHTML;
  if(chromeMarkup.get(target)!==markup){
   const top=target.scrollTop,left=target.scrollLeft;
   target.replaceChildren(...source.childNodes);
   target.scrollTop=top;target.scrollLeft=left;
   chromeMarkup.set(target,markup);
  }
 };
 [...nextSidebar.children].forEach((source,index)=>syncChildren(sidebar.children[index],source));
 sidebar.querySelectorAll('.side-nav a').forEach(a=>{
  const active=a.getAttribute('href')===activeHref;
  a.classList.toggle('active',active);
  if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');
 });
 const main=current.querySelector(':scope > .main'),nextMain=next.querySelector(':scope > .main');
 for(const selector of ['.demo-banner','.topline','.mobile-nav'])syncChildren(main.querySelector(':scope > '+selector),nextMain.querySelector(':scope > '+selector));
 main.querySelector(':scope > .content').replaceChildren(...nextMain.querySelector(':scope > .content').childNodes);
}
function render(){if(!user)return login();syncActivePrices();const r=route(),page=r.split('/')[0];let content;try{if(recordDetailPages.includes(page))content=recordDetailView(page,r.split('/'));else if(page==='quote')content=quoteDetail(r.split('/')[1]);else if(page==='print')content=printView(r.split('/')[1]);else if(['new','edit'].includes(page))content=editor();else{const views={process:processView,overview:workflowOverview,quotes:()=>workflowQuotes(),approvals:()=>workflowQuotes(true),sent:()=>workflowQuotes(false,true),'request-new':workflowRequestNew,'request-form':rfqFormPage,'supplier-waiting':()=>workflowRequests(true),'internal-pending':()=>rfqRegister(),'request-tracking':workflowRequests,'request-register':()=>rfqRegister(),'request-review':()=>rfqRegister(true),'request-drafts':()=>rfqRegister(),'request-dispatch':()=>rfqRegister(),schedule:dueReviewView,'schedule-active':activeScheduleView,records:recordsView,requests:workflowRequests,parts,suppliers:accounts,history:historyView,exports:exportsView,reports:reportsView,outbox:outboxView,formulas:formulasView};const valid=workflowCanOpen(page);content=valid&&views[page]?views[page]():'<div class="empty">This page is unavailable in this portal. <a href="#overview">Return to overview</a></div>'}updateWorkspace(content,page);bindInputs()}catch(e){console.error(e);updateWorkspace('<div class="empty">This view could not be loaded. <a href="#overview">Return to overview</a></div>',page)}}
function refreshRows(){document.getElementById('cost-rows').innerHTML=costRowsUI();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===costTab));bindCostInputs()}
function refreshTotals(){const c=window.formCosts,t=totals(c),s=sectionsOf(c).find(s=>s.key===costTab);document.querySelectorAll('[data-expense]').forEach(el=>{const r=c[costTab][+el.dataset.expense];if(r)el.textContent=cash(amountOf(c,s,r))});document.querySelectorAll('[data-sum]').forEach(el=>{const k=el.dataset.sum;el.textContent=k==='change'?signedPct(t.total,window.formBaseTotal):cash(t[k])})}
function bindSummaryInputs(){['profit','spare','basis'].forEach(key=>{const el=document.getElementById(key);if(el)el.oninput=el.onchange=()=>{window.formCosts[key]=key==='basis'?el.value:(el.value===''?null:Number(el.value));refreshTotals()}})}
function bindCostInputs(){document.querySelectorAll('[data-cost]').forEach(el=>el.oninput=el.onchange=()=>{window.formCosts[costTab][+el.dataset.cost][el.dataset.field]=el.type==='number'?(el.value===''?NaN:Number(el.value)):el.value;refreshTotals()});document.querySelectorAll('[data-adj]').forEach(el=>el.oninput=()=>{window.formCosts[el.dataset.adj]=el.value===''?NaN:Number(el.value);refreshTotals()});document.querySelectorAll('[data-adj-basis]').forEach(el=>el.onchange=()=>{window.formCosts[el.dataset.adjBasis]=el.value;refreshTotals()})}
function rerenderSearch(el){const id=el.id,pos=el.selectionStart;search=el.value;render();const replacement=document.getElementById(id);replacement?.focus();try{replacement?.setSelectionRange(pos,pos)}catch{}}
function bindInputs(){installRecordRows();const s=document.getElementById('search');if(s)s.oninput=()=>rerenderSearch(s);[['status-filter',v=>filterStatus=v],['format-filter',v=>formatFilter=v],['supplier-filter',v=>filterSupplier=v],['price-filter',v=>priceFilter=v]].forEach(([id,set])=>{const el=document.getElementById(id);if(el)el.onchange=()=>{set(el.value);render()}});const all=document.getElementById('select-all');if(all){const checks=[...document.querySelectorAll('[data-select]:not(:disabled)')];all.checked=checks.length>0&&checks.every(c=>c.checked);all.indeterminate=!all.checked&&checks.some(c=>c.checked);all.onchange=()=>selectRequestPage(all.checked);}const cw=document.getElementById('compare-with');if(cw)cw.onchange=()=>{compareWith=cw.value;render()};const rc=document.getElementById('report-code');if(rc)rc.onchange=()=>{reportCode=rc.value;location.hash='reports/'+encodeURIComponent(rc.value)};const form=document.getElementById('quote-form');if(form){form.onsubmit=e=>{e.preventDefault();saveQuote(true)};bindCostInputs();bindSummaryInputs();document.getElementById('item').onchange=e=>{const item=db.items.find(i=>i.id===e.target.value&&i.supplier===user.supplier);if(!item)return;const n=db.notifications.find(n=>n.id===editorRequest&&n.items.includes(item.id));if(!n)return toast('Select a part in this request.');editorItem=item.id;window.formCosts=n.forms?.[item.id]?structuredClone(n.forms[item.id].costs):startingCosts(item.id);costTab=sectionsOf(window.formCosts)[0].key;render()};document.getElementById('images').onchange=e=>addFiles(e.target).catch(()=>toast('The selected file could not be read.'));document.getElementById('drawings').onchange=e=>addFiles(e.target).catch(()=>toast('The selected file could not be read.'));}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a,tr[data-open],tr[data-report]');if(!b)return;if((typeof handleCatalogClick==='function'&&handleCatalogClick(b))||(typeof handleFormulaClick==='function'&&handleFormulaClick(b)))return;if(b.dataset.open&&!e.target.closest('a,button'))return go('quote/'+b.dataset.open);if(b.dataset.edit)return editQuote(b.dataset.edit);if(b.dataset.transition)return transitionDialog(b.dataset.id,b.dataset.transition);if(b.dataset.schedule)return editSchedule(b.dataset.schedule);if(b.dataset.tab){costTab=b.dataset.tab;return refreshRows()}if(b.dataset.cmpTab){detailTab=b.dataset.cmpTab;return render()}if(b.dataset.report){reportCode=b.dataset.report;location.hash='reports/'+encodeURIComponent(b.dataset.report);return}if(b.dataset.remove!==undefined){window.formCosts[costTab].splice(+b.dataset.remove,1);refreshRows();return refreshTotals()}if(b.dataset.removeFile!==undefined){editorAttachments.splice(+b.dataset.removeFile,1);document.getElementById('attachment-list').innerHTML=attachmentUI();return}if(b.dataset.request)return newQuote(b.dataset.item,b.dataset.request);if(b.dataset.file!==undefined){const q=visibleQuotes().find(q=>q.id===b.dataset.quote),f=q?.attachments[+b.dataset.file];if(!f)return;const a=document.createElement('a');a.href=f.data;a.download=f.name;a.click();return}const a=b.dataset.action;if(!a)return;if(a==='login'){user=users.find(u=>u.id===document.getElementById('demo-account').value&&u.portal===portal);sessionStorage.setItem('roki-session-'+portal,user.id);if(!workflowCanOpen(route().split('/')[0]))return go('overview');return render()}if(a==='reset-demo')return resetDemoDialog();if(a==='confirm-reset-demo')return confirmResetDemo();if(a==='logout'){sessionStorage.removeItem('roki-session-'+portal);user=null;editing=null;window.formCosts=null;selected.clear();closeDialog();return login()}if(a==='new')return go('requests');if(a==='save-draft')return saveQuote(false);if(a==='close')return closeDialog();if(a==='confirm-transition')return confirmTransition();if(a==='notify')return notifyDialog();if(a==='send-notifications')return sendNotifications();if(a==='export')return exportCSV();if(a==='export-history')return exportHistoryCSV();if(a==='print')return window.print();if(a==='add-cost'){const sec=sectionsOf(window.formCosts).find(s=>s.key===costTab);window.formCosts[costTab].push(blankRow(sec));refreshRows();refreshTotals();}});
document.addEventListener('change',e=>{if(e.target.dataset.select){toggleRequestSelection(e.target.dataset.select,e.target.checked)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog();if(e.key==='Tab'&&document.querySelector('.dialog')){const focusable=[...document.querySelectorAll('.dialog button,.dialog input,.dialog textarea,.dialog select')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus()}}});
window.addEventListener('hashchange',()=>{requestSelectionFor=null;rfqDeliveryFilter='';priceFilter='';selected.clear();search='';filterStatus='';formatFilter='';filterSupplier='';render()});
window.addEventListener('storage',e=>{if(e.key===STORE){if(e.newValue===null){location.reload();return}try{db=JSON.parse(e.newValue)||seed();prepareSourcingData();prepareLifecycleData();setFormulaStore(db.formulas);if(user&&!['new','edit'].includes(route().split('/')[0])&&!document.querySelector('.dialog'))render()}catch{}}});
